INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','small-quantities','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"small-quantities","title":"Few, a few, little and a little","level":"A2","order":15,"summary":"Distinguish a small useful amount from a shortage, with countable and uncountable nouns.","learningGoals":["A positive small amount","Emphasising a shortage","Read the meaning as well as the noun"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"A positive small amount","explanation":"A few goes with plural countable nouns. A little and a bit of go with uncountable nouns. These expressions can present the amount positively.","examples":["A few volunteers can help.","We have a little energy left."]},{"title":"Emphasising a shortage","explanation":"Few with plural nouns and little or very little with uncountable nouns emphasise scarcity. The surrounding context tells us whether the quantity feels sufficient.","examples":["Few volunteers signed up; we need more.","There is very little energy left."]},{"title":"Read the meaning as well as the noun","explanation":"A few and few have different emphasis despite both referring to small numbers. Do not treat all small quantities as shortages.","examples":["We have a few useful ideas.","We have few useful ideas, unfortunately."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-small-quantities"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"4a919d93-8087-5b2e-a944-fb544ad4e6af","topicSlug":"small-quantities","level":"A2","prompt":"For collecting postage stamps, present a small available quantity positively: “We have ____ stamps available.” Choose the small-quantity phrase.","choices":[{"id":"A","text":"a little"},{"id":"B","text":"very little"},{"id":"C","text":"a few"},{"id":"D","text":"few"}],"answerId":"C","hint":"A few goes with plural countable nouns. A little and a bit of go with uncountable nouns. These expressions can present the amount positively. Focus on **positive amount** in this question.","explanation":"a few presents a small quantity of stamps positively. Use a few with plural countable nouns.","keywords":[],"source":"seed","skill":"positive-amount","contextKey":"quantity-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-small-quantities"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"7a299ff70aaf09aa106dd01b74a79f6912e905b6fe9c359449603cafc3ac4889","teaching":{"steps":["Identify what the question tests: **positive amount**. A few goes with plural countable nouns. A little and a bit of go with uncountable nouns. These expressions can present the amount positively.","a few presents a small quantity of stamps positively. Use a few with plural countable nouns.","Choose **a few**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**a little** fits uncountable nouns. This question uses the other kind of noun in its stated sense. a few presents a small quantity of stamps positively. Use a few with plural countable nouns.","B":"**very little** fits uncountable nouns. This question uses the other kind of noun in its stated sense. a few presents a small quantity of stamps positively. Use a few with plural countable nouns.","C":"a few presents a small quantity of stamps positively. Use a few with plural countable nouns.","D":"The quantity-word family fits, but **few** changes the emphasis: the prompt asks for a small amount presented positively. a few presents a small quantity of stamps positively. Use a few with plural countable nouns."}}},{"id":"bbb10429-a02a-55ca-ab99-ac780ccf988b","topicSlug":"small-quantities","level":"A2","prompt":"For collecting postage stamps, emphasise that the quantity is almost zero: “We have ____ stamps, unfortunately.”","choices":[{"id":"A","text":"a few"},{"id":"B","text":"a little"},{"id":"C","text":"very little"},{"id":"D","text":"few"}],"answerId":"D","hint":"Few with plural nouns and little or very little with uncountable nouns emphasise scarcity. The surrounding context tells us whether the quantity feels sufficient. Focus on **shortage** in this question.","explanation":"few emphasises scarcity with plural countable stamps.","keywords":[],"source":"seed","skill":"shortage","contextKey":"quantity-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-small-quantities"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"55cce5edc3cfa322decc1221c33df1a664b8b73074347e6fc9f6a8b38084a7fc","teaching":{"steps":["Identify what the question tests: **shortage**. Few with plural nouns and little or very little with uncountable nouns emphasise scarcity. The surrounding context tells us whether the quantity feels sufficient.","few emphasises scarcity with plural countable stamps.","Choose **few**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"The quantity-word family fits, but **a few** changes the emphasis: the prompt asks for scarcity, almost none. few emphasises scarcity with plural countable stamps.","B":"**a little** fits uncountable nouns. This question uses the other kind of noun in its stated sense. few emphasises scarcity with plural countable stamps.","C